"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["58718"],{12363(e){e.exports=JSON.parse('{"id":"FIN-1002","slug":"tax-compliance","term":"Tax Compliance","also_known_as":[],"difficulty":"Intermediate","definition":"Tax compliance is meeting all the tax obligations set by law: registering where required, keeping records, filing accurate returns and paying the right amount of tax on time.","explanation":["Every tax system depends on people and businesses following its rules. Compliance covers practical tasks such as keeping receipts and invoices, reporting all income, claiming only the deductions allowed and meeting filing and payment deadlines.","For a small business, compliance might mean registering for sales tax or value-added tax, charging it correctly on sales, filing returns each quarter and paying payroll taxes for employees each month. Missing a deadline can bring penalties and interest, even if the tax itself is eventually paid.","Compliance is different from tax planning. Planning means arranging affairs legally to reduce tax, while compliance means reporting and paying correctly under whatever arrangements have been made. Tax evasion, deliberately hiding income or inventing expenses, is a breach of compliance and a crime.","Tax authorities encourage compliance through clear guidance, digital filing, information reporting by employers and banks, audits and penalties. For large companies, compliance is a specialist function, because they may file in many countries under different rules."],"note":"","total":1500,"prev":{"slug":"tax-bracket","term":"Tax Bracket"},"next":{"slug":"tax-credit","term":"Tax Credit"}}')}}]);